const modal=document.querySelector('#modal'),body=document.querySelector('#modal-body');
let returnFocus=null;
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readVoices(){try{return JSON.parse(localStorage.getItem('eof-voces')||'[]').filter(v=>typeof v==='string').slice(-20)}catch{return[]}}
const action=(id,text)=>`<button class="pill" data-modal="${id}">${text} <span>↗</span></button>`;
function openModal(id){window.PortraitCamera.destroy();window.OdioNetwork.destroy();modal.classList.toggle("network-mode",id==="mapa");modal.classList.toggle("camera-mode",id==="retrato");if(!modal.open)returnFocus=document.activeElement;document.querySelector('#modal-index').textContent='EL ODIO EN FRANCÉS / '+id.toUpperCase();const views={
intro:()=>`<p class="eyebrow">EMPEZÁ POR DONDE TE SALGA.</p><h2>NO HACE FALTA<br>TENER LAS PALABRAS.</h2><p>Podés escribir lo que te pasa, leer otras voces o explorar cómo te sentís. Cada entrada abre un camino distinto.</p><div class="modal-actions">${action('escribir','QUIERO SOLTAR')}${action('voces','QUIERO LEER')}${action('retrato','QUIERO MIRARME')}</div>`,
mapa:()=>window.OdioNetwork.markup(),
escribir:()=>`<p class="eyebrow">UN POCO MENOS ADENTRO.</p><h2>¿QUÉ TE ESTÁ<br>COMIENDO HOY?</h2><form id="voice-form"><label for="voice">ESCRIBILO COMO TE SALGA.</label><textarea id="voice" maxlength="500" required placeholder="Me da bronca que…"></textarea><div class="form-info"><span>Se guarda solo en este navegador.</span><span id="count">0 / 500</span></div><div class="modal-actions"><button class="pill" type="submit">SOLTARLO <span>↗</span></button></div><p id="save-error" role="status"></p></form>`,
voces:()=>`<p class="eyebrow">HAY ALGO DE VOS EN OTRAS VOCES.</p><h2>LA BRONCA<br>SE COMPARTE.</h2><small class="empty">TEXTOS DE EJEMPLO · TUS ENTRADAS SON LOCALES</small>${[...readVoices().reverse().map(t=>[t,'TU VOZ · EN ESTE NAVEGADOR']),['Me cansé de tener que poder con todo.','VOZ DE EJEMPLO / 01'],['A veces sonrío cuando en realidad quiero gritar.','VOZ DE EJEMPLO / 02'],['Que me escuchen sin decirme qué hacer. Eso.','VOZ DE EJEMPLO / 03']].map(([t,l])=>`<article class="voice"><p>“${escapeHTML(t)}”</p><small>${l}</small></article>`).join('')}<div class="modal-actions">${action('escribir','SUMAR MI VOZ')}${action('mapa','VOLVER A LA RED')}</div>`,
guardado:()=>`<p class="eyebrow">YA NO ESTÁ SOLO ADENTRO.</p><h2>LE DISTE<br>UN LUGAR.</h2><p>Tu texto quedó guardado en este navegador. Podés encontrarlo en otras voces.</p><div class="modal-actions">${action('voces','VER MI VOZ')}${action('retrato','SEGUIR CON MI RETRATO')}</div>`,
retrato:()=>window.PortraitCamera.markup(),
acerca:()=>`<p class="eyebrow">EL ODIO EN FRANCÉS.</p><h2>LO QUE SENTÍS<br>TAMBIÉN CONECTA.</h2><p>Un recorrido visual para poner en palabras la bronca, encontrarte en otras voces y explorar la distancia entre lo que mostrás y lo que sentís.</p><p>Prototipo local a partir de la referencia visual. Las voces de ejemplo son ilustrativas. Tus textos quedan en este dispositivo y no se publican.</p><div class="modal-actions">${action('mapa','EXPLORAR LA RED')}</div>`};
body.innerHTML=(views[id]||views.intro)();body.scrollTop=0;if(!modal.open){modal.showModal();document.body.style.overflow='hidden'}modal.scrollTop=0;document.querySelector('#close').focus();if(id==="retrato")window.PortraitCamera.init();if(id==="mapa")window.OdioNetwork.init();}
function closeModal(){modal.close()}
document.addEventListener("click",e=>{const a=e.target.closest("[data-modal]");if(a)openModal(a.dataset.modal)});
document.querySelector('#close').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});modal.addEventListener('close',()=>{window.PortraitCamera.destroy();window.OdioNetwork.destroy();modal.classList.remove("camera-mode","network-mode");document.body.style.overflow='';returnFocus?.focus()});
document.addEventListener('input',e=>{if(e.target.id==='voice')document.querySelector('#count').textContent=e.target.value.length+' / 500'});
document.addEventListener('submit',e=>{if(e.target.id!=='voice-form')return;e.preventDefault();const value=document.querySelector('#voice').value.trim();if(!value){document.querySelector('#save-error').textContent='Escribí algo antes de soltarlo.';return}try{localStorage.setItem('eof-voces',JSON.stringify([...readVoices(),value].slice(-20)));openModal('guardado')}catch{document.querySelector('#save-error').textContent='No se pudo guardar. Revisá si el navegador permite almacenamiento local.'}});



// La navegación acompaña la sección visible durante el recorrido.
const sectionObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;document.querySelectorAll(".header nav a").forEach(link=>{if(link.hash==="#"+entry.target.id)link.setAttribute("aria-current","location");else link.removeAttribute("aria-current")})}},{rootMargin:"-20% 0px -45% 0px",threshold:0});
document.querySelectorAll("main>section").forEach(section=>sectionObserver.observe(section));
